#include <string.h>

char* allocate_buffer_and_write(size_t buf_size) {
    if (buf_size < 20) {
        return NULL; // Not enough space to write 'A' to the first and last 10 bytes
    }

    char* buffer = (char*)malloc(buf_size);
    if (buffer == NULL) {
        return NULL; // Allocation failed
    }

    // Write 'A' to the first 10 bytes
    memset(buffer, 'A', 10);

    // Write 'A' to the last 10 bytes
    if (buf_size > 20) {
        memset(buffer + buf_size - 10, 'A', 10);
    } else {
        // If buf_size is exactly 20, the first and last 10 bytes overlap
        memset(buffer, 'A', 20);
    }

    return buffer;
}
